#!/usr/bin/perl
# probe.pl <label> <perl-expr-producing-arg-bytes-or-UNDEF>
# Runs the reference binary with the given raw arg bytes, prints stdout/stderr/status precisely.
use strict; use warnings;
use POSIX ":sys_wait_h";

my $BIN = $ENV{BIN} // "/workspace/dataset/test7_executable";

sub runit {
    my ($argref) = @_;   # arrayref of args (may be empty)
    my $outf = "/tmp/p.out"; my $errf = "/tmp/p.err";
    unlink $outf, $errf;
    my $pid = fork();
    die "fork" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, ">", $outf) or die;
        open(STDERR, ">", $errf) or die;
        exec($BIN, @$argref) or POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $raw = $?;
    my $out = do { local $/; open(my $fh, "<", $outf) or die; binmode $fh; <$fh> } // "";
    my $err = do { local $/; open(my $fh, "<", $errf) or die; binmode $fh; <$fh> } // "";
    return ($raw, $out, $err);
}

sub shellstatus {
    my ($raw) = @_;
    if (WIFSIGNALED($raw)) { return 128 + WTERMSIG($raw); }
    return WEXITSTATUS($raw);
}

sub esc { my $s = shift; $s =~ s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; return $s; }

my $label = shift @ARGV;
my $expr  = shift @ARGV;
my @args;
if (defined $expr && $expr ne 'NOARG') {
    my $a = eval $expr;
    die "eval err: $@" if $@;
    @args = ($a);
}
my ($raw, $out, $err) = runit(\@args);
my $ss = shellstatus($raw);
printf("%-28s raw=%-6d shell=%-4d sig=%s\n", $label, $raw, $ss, (WIFSIGNALED($raw)? WTERMSIG($raw) : "-"));
printf("  STDOUT(%d): %s\n", length($out), esc($out));
printf("  STDERR(%d): %s\n", length($err), esc($err));

