use POSIX ":sys_wait_h";

my $BIN = $ENV{BIN} // "/workspace/dataset/test7_executable";

sub runit {
    my ($argref) = @_;
    my $outf = "/tmp/b.out"; my $errf = "/tmp/b.err";
    unlink $outf, $errf;
    my $pid = fork(); die "fork" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, ">", $outf) or die; open(STDERR, ">", $errf) or die;
        exec($BIN, @$argref); POSIX::_exit(127);
    }
    waitpid($pid, 0);
    my $raw = $?;
    my $out = do { local $/; open(my $fh,"<",$outf) or die; binmode $fh; <$fh> } // "";
    my $err = do { local $/; open(my $fh,"<",$errf) or die; binmode $fh; <$fh> } // "";
    return ($raw, $out, $err);
}

while (my $line = <STDIN>) {
    chomp $line;
    next if $line =~ /^\s*$/ || $line =~ /^#/;
    my ($label, $expr) = split(/\t/, $line, 2);
    my @args;
    if (defined $expr && $expr ne 'NOARG') {
        my $a = eval $expr; die "eval err for $label: $@" if $@;
        @args = ($a);
    }
    my ($raw,$out,$err) = runit(\@args);
    my $ss = WIFSIGNALED($raw) ? 128+WTERMSIG($raw) : WEXITSTATUS($raw);
    my $verdict;
    if ($out =~ m{^Progress: [-0-9.e+]+% \((-?\d+)/200\)}) {
        $verdict = "OK  n=$1";
    } elsif ($err =~ /std::(invalid_argument|out_of_range)/) {
        $verdict = "ERR $1";
        $verdict .= "  [STDOUT NOT EMPTY: ".length($out)."]" if length($out);
    } else {
        $verdict = "??? out=".length($out)." err=".length($err);
    }
    printf("%-34s status=%-4d %s\n", $label, $ss, $verdict);
}

