use std::io::Write;
use std::os::unix::ffi::OsStrExt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    InvalidArgument,
    OutOfRange,
}

impl StoiError {
    pub fn cxx_type_name(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }
}

#[inline]
fn is_c_space(b: u8) -> bool {
    b == b' ' || (0x09..=0x0d).contains(&b)
}

pub fn c_stoi(s: &[u8]) -> Result<i32, StoiError> {
    let mut i = 0usize;
    while i < s.len() && is_c_space(s[i]) {
        i += 1;
    }
    let mut neg = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        neg = s[i] == b'-';
        i += 1;
    }
    let digits_start = i;
    let mut acc: i64 = 0; // accumulated NEGATIVELY, like strtol
    let mut overflowed = false;
    while i < s.len() && s[i].is_ascii_digit() {
        if !overflowed {
            acc = acc * 10 - ((s[i] - b'0') as i64);
            if acc < i32::MIN as i64 {
                overflowed = true;
            }
        }
        i += 1;
    }
    if i == digits_start {
        return Err(StoiError::InvalidArgument);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }
    let v = if neg { acc } else { -acc };
    if v < i32::MIN as i64 || v > i32::MAX as i64 {
        return Err(StoiError::OutOfRange);
    }
    Ok(v as i32)
}

fn die(e: StoiError) -> ! {
    let msg = format!(
        "terminate called after throwing an instance of '{}'\n  what():  stoi\n",
        e.cxx_type_name()
    );
    let mut err = std::io::stderr();
    let _ = err.write_all(msg.as_bytes());
    let _ = err.flush();
    std::process::abort();
}

fn main() {
    // GOTCHA: env::args() panics on non-UTF-8 argv. Must use args_os().
    let arg = std::env::args_os().nth(1);
    let progress: i32 = match arg {
        Some(a) => match c_stoi(a.as_bytes()) {
            Ok(v) => v,
            Err(e) => die(e),
        },
        None => 150,
    };
    // Minimal stand-in for the rest of the program so the parsed value is observable
    // in the same shape the reference binary prints it.
    let total: i32 = 200;
    let mut current = progress;
    let pct = |c: i32| (c as f32) * 100.0f32 / (total as f32);
    println!("Progress: {:.1}% ({}/{})", pct(current), current, total);
    current = current.wrapping_add(25);
    println!("Progress: {:.1}% ({}/{})", pct(current), current, total);
    println!("{:.1}%", 0.15f32 * 100.0f32);
    println!("{:.2}%", 0.35f32 * 100.0f32);
    println!("{:.3}%", 0.65f32 * 100.0f32);
}

